@@ -0,0 +1,54 @@
+import http from "http";
+import { claimNext, completeJob } from "./jobs.ts";
+
+const API_KEY = process.env.API_KEY;
+const PORT = parseInt(process.env.PORT || "3000", 10);
+
+const authenticate = (req: http.IncomingMessage): boolean => {
+  if (!API_KEY) return true;
+  const token = req.headers.authorization?.replace("Bearer ", "");
+  return token === API_KEY;
+};
+
+export const startAPI = (): void => {
+  const server = http.createServer(async (req, res) => {
+    if (!authenticate(req)) {
+      res.writeHead(401, { "Content-Type": "application/json" });
+      res.end(JSON.stringify({ error: "Unauthorized" }));
+      return;
+    }
+
+    if (req.method === "GET" && req.url === "/jobs/next") {
+      try {
+        const job = await claimNext();
+        res.writeHead(200, { "Content-Type": "application/json" });
+        res.end(JSON.stringify(job));
+      } catch {
+        res.writeHead(500, { "Content-Type": "application/json" });
+        res.end(JSON.stringify({ error: "Internal Server Error" }));
+      }
+      return;
+    }
+
+    const completeMatch = req.url?.match(/^\/jobs\/([^/]+)\/complete$/);
+    if (req.method === "POST" && completeMatch) {
+      const jobId = completeMatch[1];
+      try {
+        await completeJob(jobId);
+        res.writeHead(200, { "Content-Type": "application/json" });
+        res.end(JSON.stringify({ ok: true }));
+      } catch {
+        res.writeHead(500, { "Content-Type": "application/json" });
+        res.end(JSON.stringify({ error: "Internal Server Error" }));
+      }
+      return;
+    }
+
+    res.writeHead(404);
+    res.end();
+  });
+
+  server.listen(PORT, () => {
+    console.log(`API listening on port ${PORT}`);
+  });
+};
